#!/usr/bin/env bash
# Negative controls: each config below must be REFUSED by the toolchain's `lake comparator`, for
# the reason given. A control that is accepted, or refused for another reason, fails this script.
#
# applies_to: this repository's Challenge.lean / Solution.lean / comparator.json, at the pinned
# toolchain. Each Controls/*.lean is Challenge.lean with exactly one edit (see its first comment;
# regenerated by scripts/make_controls.py).
#
# `lake comparator` builds the challenge module itself and ignores `lake -f`, so the control
# library has to be in lakefile.toml while it runs. This script appends it and restores the
# original lakefile.toml on exit. The kernels are the ones verify-comparator.sh registers
# (Lean, NanoDa, con-ron). Usage, from the repository root, after `lake build`:
#     bash tests/controls/run-controls.sh                  # Linux, bwrap sandbox
#     bash tests/controls/run-controls.sh --no-sandbox     # e.g. Windows (no bwrap); untrusted mode
set -uo pipefail

repository_root=$(cd "$(dirname "$0")/../.." && pwd)
cd "$repository_root"

sandbox_flag=()
if [ "${1:-}" = "--no-sandbox" ]; then
  sandbox_flag=(--inadvisably-no-sandbox)
fi

prefix=$(lean --print-prefix)
python=python3
command -v python3 >/dev/null 2>&1 || python=python
exe=""
if [ -x "$prefix/bin/nanoda_bin.exe" ]; then exe=".exe"; fi

backup=$(mktemp "${TMPDIR:-/tmp}/lakefile.XXXXXX")
cp lakefile.toml "$backup"
trap 'cp "$backup" lakefile.toml; rm -f "$backup" tests/controls/.cfg-*.json' EXIT
cat >> lakefile.toml <<'TOML'

# Appended by tests/controls/run-controls.sh; removed again when it exits.
[[lean_lib]]
name = "Controls"
srcDir = "tests/controls"
globs = ["Controls.+"]
TOML

# name | expected substring of the refusal
controls=(
  "sorry-solution|Illegal axiom detected: 'sorryAx'"
  "axiom-solution|Illegal axiom detected: 'OAI.EuclideanRamsey.cheat'"
  "redef-ramsey|Const does not match between challenge and target 'OAI.EuclideanRamsey.Ramsey'"
  "card-four|Challenge and solution theorem statement do not match: 'OAI.EuclideanRamsey.ramsey_alg_plus_three'"
  "weaker-mathlib|Challenge and solution theorem statement do not match: 'AlgebraicPlusThree.ramsey_alg_plus_three_mathlib'"
)

failed=0
for entry in "${controls[@]}"; do
  name=${entry%%|*}
  expected=${entry#*|}
  config="tests/controls/.cfg-$name.json"
  "$python" - "tests/controls/$name.json" "$config" "$prefix" "$exe" <<'PY'
import json, pathlib, sys
source, destination, prefix, exe = sys.argv[1:]
# On Windows, `lean --print-prefix` prints `c:\...`; lake comparator wants `C:/...`.
prefix = pathlib.Path(prefix).resolve().as_posix()
config = json.loads(pathlib.Path(source).read_text(encoding="utf-8"))
config["external_kernels"] = {
    "nanoda": [f"{prefix}/bin/nanoda_bin{exe}"],
    "con-ron": [f"{prefix}/bin/con-ron{exe}"],
}
pathlib.Path(destination).write_text(json.dumps(config, indent=2) + "\n", encoding="utf-8")
PY
  log="tests/controls/.log-$name.txt"
  lake comparator --config "$config" "${sandbox_flag[@]}" >"$log" 2>&1
  status=$?
  if [ "$status" -ne 0 ] && grep -qF "$expected" "$log"; then
    echo "REFUSED as expected: $name (exit $status): $expected"
  else
    echo "CONTROL FAILED: $name (exit $status); see $log"
    tail -5 "$log"
    failed=1
  fi
done
exit "$failed"
